// nextcuda 3D server (nextcuda model3d serve): the routes' types and a typed client.
// Generated by rpcgen from the #[route] handlers: do not edit; regenerate.
/* eslint-disable */

/** What the engine does */
export interface Abilities {
  /** makes meshes from pictures */
  generate: boolean;
  /** paints them (a texture) */
  texture: boolean;
  /** the most views (pictures) a mesh is made from */
  views: number;
  /** rigs a mesh (a skeleton and skin weights) */
  rig: boolean;
  /** animates one (a motion in words) */
  animate: boolean;
}

/** What a cancel takes */
export interface CancelReq {
  /** that request only (the front door's job), running or waiting; none: the one running */
  id?: string | null;
}

/** What a cancel did */
export interface Cancelled {
  /** a request running was told to stop */
  cancelled: boolean;
  id?: string | null;
}

/** The engine's own defaults (a request's absent fields) */
export interface Defaults {
  steps: number;
  cfg: number;
  resolution: number;
  faces: number;
  texture_size: number;
  frames: number;
  fps: number;
}

/** An option of the engine's own (a request sends it in `options`) */
export interface EngineOptionInfo {
  name: string;
  /** what its value looks like ("" a flag) */
  value: string;
  help: string;
}

/** A file a link names (`.../files/{name}`) */
export interface FileName {
  /** the file's name as the answer's url has it */
  name: string;
}

/** The card a model server runs on, as its page shows it */
export interface Gpu {
  name: string;
  vram_used_mb: number;
  vram_total_mb: number;
  /** watts now (none: the driver does not say) */
  power_w?: number | null;
  /** °C */
  temp_pkg?: number | null;
  /** the memory's °C */
  temp_vram?: number | null;
}

/** Whether the server answers (and has its model loaded) */
export interface Health {
  /** ok, or loading (HTTP 503 then) */
  status: string;
}

/** The meshes in the output directory, newest first (read from it each time) */
export interface History {
  data: Mesh[];
}

/** The model and what it does; while a request runs, the model and `busy` only */
export interface Info {
  model: string;
  /** the licence of its weights, whether it allows commercial use (false: the page tags it non-commercial), the conditions it puts on it */
  license?: string | null;
  commercial?: boolean | null;
  license_note?: string | null;
  /** the engine is running a request: what changes is not reported */
  busy?: boolean | null;
  arch?: string | null;
  /** it serves its page */
  wfe?: boolean | null;
  abilities?: Abilities | null;
  defaults?: Defaults | null;
  /** the engine's own per-request options (sent as `options`) */
  options?: EngineOptionInfo[] | null;
  /** what the engine says of itself (its files, its precision ...) */
  report?: string[] | null;
  /** it keeps what it makes (an output directory: links, the history) */
  saves?: boolean | null;
}

/** A mesh made here: its links, and its settings (its sidecar <name>.json) */
export interface Mesh {
  /** the GLB (glTF binary): GET it here */
  url: string;
  /** the picture it was made from (PNG) */
  picture?: string | null;
  bytes: number;
  /** unix seconds */
  created: number;
  model?: string | null;
  arch?: string | null;
  seed?: number | null;
  steps?: number | null;
  cfg?: number | null;
  resolution?: number | null;
  /** the triangle budget asked */
  faces?: number | null;
  /** what it has */
  triangles?: number | null;
  /** a texture was asked for */
  texture?: boolean | null;
  /** it has one */
  textured?: boolean | null;
  /** rigged: its joints */
  rigged?: number | null;
  /** animated: its frames */
  animated?: number | null;
  /** a rig's motion */
  prompt?: string | null;
  /** rig: the frames asked */
  frames?: number | null;
  /** each picture's side (null: not said) */
  views?: (string | null)[] | null;
  /** seconds it took */
  took?: number | null;
  /** the card's energy, watt-hours */
  wh?: number | null;
  /** other keys */
  [key: string]: unknown;
}

/** How a mesh was made */
export interface MeshRun {
  took: number;
  seed: number;
  wh?: number | null;
  triangles: number;
}

/** A mesh made (response_format url): its links and settings, and how it was made (`nextcuda`: this server's key) */
export interface Meshes {
  created: number;
  data: Mesh[];
  nextcuda: MeshRun;
}

/** What model3d.generate makes from: the body its kind's server takes. */
export interface Model3dGenerateBody {
  /** guidance */
  cfg?: number | null;
  /** at most this many triangles (decimated to it) */
  faces?: number | null;
  /** or a GLB made here to paint (its file name or url), as mesh */
  file?: string | null;
  /** the picture: PNG, JPEG or WebP as base64, a data: URL or upload:<name> (model3d.upload); a transparent background is the object's outline, an opaque one is cut out (remove_background) (or {image, side}, as an item of images) */
  image?: unknown | null;
  /**
   * several views of the object (a multi-view model: model3d.info's abilities.views); each a picture or {image, side}
   * @maxItems 8
   * @items {"oneOf":[{"type":"string"},{"properties":{"image":{"type":"string"},"side":{"description":"front, back, left, right, top, bottom, or an azimuth in degrees","type":"string"}},"type":"object"}]}
   */
  images?: unknown[] | null;
  /** a mesh to paint instead of making one (a model that textures: Hunyuan3D 2.1, hunyuan3d-2.1-paint): a GLB or OBJ as base64 or a data: URL; image says how it is painted */
  mesh?: string | null;
  /** the model's id; none: the loaded one, else the first enabled */
  model?: string | null;
  /** the engine's own (model3d.info lists them) */
  options?: Record<string, unknown> | null;
  /**
   * cut the background out of an opaque picture
   * @default true
   */
  remove_background?: boolean | null;
  /** the shape's grid / octree resolution: detail against time and memory */
  resolution?: number | null;
  seed?: number | null;
  /** denoising steps of each stage */
  steps?: number | null;
  /** PBR textures too (base colour, metallic-roughness); default: what the model does (model3d.info) */
  texture?: boolean | null;
  /** the texture's side in texels */
  texture_size?: number | null;
  /** other keys */
  [key: string]: unknown;
}

/** What model3d.rig makes from: the body its kind's server takes. */
export interface Model3dRigBody {
  cfg?: number | null;
  /** or a GLB made here (model3d.generate's file name or url) */
  file?: string | null;
  fps?: number | null;
  /** an animating model: frames to make */
  frames?: number | null;
  /** the mesh: GLB or OBJ as base64, a data: URL or upload:<name> (model3d.upload) */
  mesh?: string | null;
  /** the model's id; none: the loaded one, else the first enabled */
  model?: string | null;
  /** the engine's own */
  options?: Record<string, unknown> | null;
  /** an animating model: the motion, in words ("a dragon flapping its wings") */
  prompt?: string | null;
  seed?: number | null;
  steps?: number | null;
  /** other keys */
  [key: string]: unknown;
}

/** A model in OpenAI's list */
export interface ModelEntry {
  id: string;
  /** model */
  object: string;
  owned_by: string;
  created: number;
}

/** OpenAI's list of models: the one this server serves */
export interface ModelList {
  /** list */
  object: string;
  data: ModelEntry[];
}

/** What the server is doing: busy false, or what it is making and how far it is */
export interface Progress {
  busy: boolean;
  /** the pictures it is made from, or the motion */
  prompt?: string | null;
  /** the engine's */
  phase?: string | null;
  at?: number | null;
  of?: number | null;
  /** seconds since it started */
  seconds?: number | null;
  /** requests waiting for the engine */
  waiting?: number | null;
  /** the front door's job running, if it named one */
  request_id?: string | null;
}

/** A route's failure: the words its body's `error` said, and the body. */
export class RouteError extends Error {
  constructor(message: string, readonly body: unknown) {
    super(message);
  }
}

function runtime(base: string, fetcher: typeof fetch) {
  const words = (e: any): string => (typeof e === "string" ? e : (e?.message ?? JSON.stringify(e)));
  const read = async (res: Response, u: string, ownError: boolean): Promise<any> => {
    const text = await res.text();
    let v: any = null;
    try {
      v = text ? JSON.parse(text) : null;
    } catch {
      throw new RouteError(`${u}: the answer is not JSON (HTTP ${res.status})`, text);
    }
    const failed = v !== null && typeof v === "object" && !Array.isArray(v) && v.error != null && (!ownError || v.ok === false);
    if (failed) throw new RouteError(words(v.error), v);
    return v;
  };
  return {
    url(path: string, req: object, query: boolean): string {
      const fields = req as Record<string, unknown>;
      const used = new Set<string>();
      let p = path.replace(/\{([^}]+)\}/g, (_, k: string) => {
        used.add(k);
        return encodeURIComponent(String(fields[k] ?? ""));
      });
      if (query) {
        const q = new URLSearchParams();
        for (const [k, v] of Object.entries(fields)) {
          if (used.has(k) || v === undefined || v === null) continue;
          for (const x of Array.isArray(v) ? v : [v]) q.append(k, String(x));
        }
        const s = q.toString();
        if (s) p += `?${s}`;
      }
      return base + p.slice(1);
    },
    async json(method: string, u: string, body?: BodyInit, type?: string, ownError = false): Promise<any> {
      const res = await fetcher(u, { method, body, headers: type ? { "content-type": type } : undefined });
      return read(res, u, ownError);
    },
    async either(method: string, u: string, body: unknown, ownError = false): Promise<any> {
      const form = body instanceof FormData;
      const res = await fetcher(u, { method, body: form ? body : JSON.stringify(body), headers: form ? undefined : { "content-type": "application/json" } });
      return read(res, u, ownError);
    },
    async blob(method: string, u: string, body?: BodyInit, type?: string): Promise<any> {
      const res = await fetcher(u, { method, body, headers: type ? { "content-type": type } : undefined });
      if ((res.headers.get("content-type") ?? "").startsWith("application/json")) return read(res, u, false);
      return res.blob();
    },
  };
}

export function routes(base = "", fetcher: typeof fetch = (u, i) => fetch(u, i)) {
  const r = runtime(base, fetcher);
  return {
    /**
     * The card: its name, memory, power and temperatures
     * @route GET /api/gpu
     * @tags page
     */
    gpu: (): Promise<Gpu> => r.json("GET", r.url("/api/gpu", {}, true), undefined, undefined, false),
    /**
     * Whether the server answers
     * @route GET /health
     * @tags page
     */
    health: (): Promise<Health> => r.json("GET", r.url("/health", {}, true), undefined, undefined, false),
    /**
     * The model served, as OpenAI lists models
     * @route GET /v1/models
     * @alias /models
     * @tags openai
     */
    models: (): Promise<ModelList> => r.json("GET", r.url("/v1/models", {}, true), undefined, undefined, false),
    /**
     * The model and what it does: its abilities, defaults, options
     * @route GET /api/info
     * @tags page
     */
    info: (): Promise<Info> => r.json("GET", r.url("/api/info", {}, true), undefined, undefined, false),
    /**
     * What the server is doing now (the page polls it)
     * @route GET /api/progress
     * @tags page
     */
    progress: (): Promise<Progress> => r.json("GET", r.url("/api/progress", {}, true), undefined, undefined, false),
    /**
     * The meshes made here, newest first
     * @route GET /api/history
     * @tags page
     */
    history: (): Promise<History> => r.json("GET", r.url("/api/history", {}, true), undefined, undefined, false),
    /**
     * Stops a request: the one named (running or waiting), else the one running (between steps)
     * @route POST /api/cancel
     * @tags page
     */
    cancel: (req: CancelReq = {}): Promise<Cancelled> => r.json("POST", r.url("/api/cancel", req, false), JSON.stringify(req), "application/json", false),
    /**
     * A file made here: the GLB, its picture (<f>.png) or its settings (<f>.json)
     * @route GET /v1/model3d/files/{name}
     * @tags files
     * @produces model/gltf-binary, image/png, application/json
     */
    file: (req: FileName): string => r.url("/v1/model3d/files/{name}", req, true),
    /**
     * A mesh from pictures (image, or images: several views [{image, side}]), textured or not; or a mesh given (mesh / file) painted. response_format glb (default: the file) or url (JSON with its link)
     * @route POST /v1/model3d/generate
     * @tags openai
     * @produces application/json, model/gltf-binary
     */
    generate: (req: Model3dGenerateBody = {}): Promise<Meshes | Blob> => r.blob("POST", r.url("/v1/model3d/generate", req, false), JSON.stringify(req), "application/json"),
    /**
     * A mesh (mesh: GLB or OBJ, base64 / a data: URL; or file: a GLB made here) rigged - a skeleton and skin weights - or animated (prompt: the motion). response_format glb (default) or url
     * @route POST /v1/model3d/rig
     * @tags openai
     * @produces application/json, model/gltf-binary
     */
    rig: (req: Model3dRigBody = {}): Promise<Meshes | Blob> => r.blob("POST", r.url("/v1/model3d/rig", req, false), JSON.stringify(req), "application/json"),
  };
}
